ISCOUNT) AS total_discount FROM SNITCH_DB.MAPLEMONK.FACT_ITEMS_SNITCH WHERE order_timestamp::date > \'2025-01-01\' GROUP BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10), Customer_id, order_name, order_timestamp::date ), Click_charge_mapped_Beta AS ( SELECT a.*, b.* FROM SHOPIFY_CHARGED_DATA a LEFT JOIN CT_Clicked_events b ON b.phone = a.phone_no AND Charged_date >= click_date AND CASE WHEN b.campaign_channel = \'Push\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 3 WHEN b.campaign_channel = \'WhatsApp\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 WHEN b.campaign_channel = \'Sms\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 WHEN b.campaign_channel = \'Email\' THEN DATEDIFF(days, b.Click_date, a.charged_date) <= 7 ELSE DATEDIFF(days, b.Click_date, a.charged_date) <= 3 END WHERE b.Click_date IS NOT Null ), click_charge_final AS ( SELECT * FROM Click_charge_mapped_Beta QUALIFY ROW_NUMBER() OVER ( PARTITION BY Phone_no, order_name ORDER BY click_date DESC NULLS LAST, click_time DESC NULLS LAST) = 1 ) SELECT ccf.* FROM click_charge_final ccf LEFT JOIN journey_reports_summary j ON j.campaign_id = ccf.c_id AND j.run_date = ccf.click_date ); CREATE OR REPLACE TABLE campaign_labels_cleaned AS ( WITH raw AS ( SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS campaign_labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM snitch_db.maplemonk.CT_CLEVERTAP_DB a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\') AND a.campaign_id NOT IN (\'1753099592\',\'1753100151\',\'1753100666\',\'1753175787\',\'1753101169\',\'1753101430\',\'1753253552\',\'1753254018\',\'1753254120\',\'1753339568\',\'1753339471\',\'1753264726\',\'1753957559\',\'1754053751\',\'1754053644\',\'1753350802\',\'1753351025\',\'1753356912\',\'1753356978\',\'1753256023\',\'1752834990\',\'1754053876\',\'1752136011\',\'1751022333\',\'1754054106\',\'1755008860\',\'1738771106\',\'1743780334\',\'1744023026\',\'1737203919\',\'1743826165\',\'1738829230\',\'1744024889\',\'1748166392\',\'1755065366\',\'1740978249\',\'1753166642\',\'1739856954\',\'1741259483\',\'1743825958\',\'1746798665\',\'1743780087\',\'1747825397\',\'1746790020\',\'1738909183\',\'1746788998\',\'1747824886\',\'1741166678\',\'1741168362\',\'1744025425\',\'1737004843\',\'1737005227\',\'1743779275\',\'1743779146\',\'1744023956\',\'1737203875\',\'1743779011\',\'1746007871\',\'1743825792\',\'1744024451\',\'1739795074\',\'1738829398\',\'1741163643\',\'1744023687\',\'1744022795\',\'1744025675\',\'1737204081\',\'1743690450\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL UNION ALL SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS campaign_labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM SNITCH_DB.MAPLEMONK.CT_CAMPAIGNS_JULY_AUG a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\') AND a.campaign_id NOT IN (\'1753099592\',\'1753100151\',\'1753100666\',\'1753175787\',\'1753101169\',\'1753101430\',\'1753253552\',\'1753254018\',\'1753254120\',\'1753339568\',\'1753339471\',\'1753264726\',\'1753957559\',\'1754053751\',\'1754053644\',\'1753350802\',\'1753351025\',\'1753356912\',\'1753356978\',\'1753256023\',\'1752834990\',\'1754053876\',\'1752136011\',\'1751022333\',\'1754054106\',\'1755008860\',\'1738771106\',\'1743780334\',\'1744023026\',\'1737203919\',\'1743826165\',\'1738829230\',\'1744024889\',\'1748166392\',\'1755065366\',\'1740978249\',\'1753166642\',\'1739856954\',\'1741259483\',\'1743825958\',\'1746798665\',\'1743780087\',\'1747825397\',\'1746790020\',\'1738909183\',\'1746788998\',\'1747824886\',\'1741166678\',\'1741168362\',\'1744025425\',\'1737004843\',\'1737005227\',\'1743779275\',\'1743779146\',\'1744023956\',\'1737203875\',\'1743779011\',\'1746007871\',\'1743825792\',\'1744024451\',\'1739795074\',\'1738829398\',\'1741163643\',\'1744023687\',\'1744022795\',\'1744025675\',\'1737204081\',\'1743690450\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL ), tokens AS ( SELECT r.campaign_id, r.run_date, r.channel, t.index AS pos, LOWER( TRIM( REPLACE(REPLACE(REPLACE(t.value::string,\'[\',\'\'),\']\',\'\'),\'\"\',\'\') ) ) AS token FROM raw r, LATERAL SPLIT_TO_TABLE( REPLACE(r.campaign_labels, \'|\', \',\'), \',\' ) t WHERE TRIM(t.value::string) <> \'\' ), tok AS ( SELECT campaign_id, run_date, channel, pos, token, LEAD(token) OVER (PARTITION BY campaign_id, run_date ORDER BY pos) AS next_token FROM tokens ), classified AS ( SELECT campaign_id, run_date, channel, token, CASE WHEN token IN (\'active new\',\'active a2c users (no purchase yet)\', \'active new users (no purchase yet)\') THEN \'Active new users (no purchase yet)\' WHEN token IN (\'add to cart\',\'recent a2c users\',\'recent a2c app users (under 45 days)\') THEN \'Recent A2C app users (under 45 days)\' WHEN token IN (\'recent a2c web users (under 45 days)\') THEN \'Recent a2c web users (under 45 days)\' WHEN token IN (\'recent app users\',\'app users less than 180 days\', \'recent app users (under 180 days)\') THEN \'Recent app users (under 180 days)\' WHEN token = \'app users less than 365 days\' THEN \'Recent app users (under 365 days)\' WHEN token IN (\'app users less than 90 days\', \'recent app users (under 90 days)\') THEN \'Recent app users (under 90 days)\' WHEN token IN (\'recent app users (45 days)\', \'recent app users (under 45 days)\',\'recent app users under 45 days\',\'recent app users less than 45 days\',\'recent shoppers (less than 30 days)\', \'recent purchasers\', \'active existing\') THEN \'Recent app users (under 45 days)\' WHEN token IN (\'online + offline\',\'offline to online\',\'offline to online shoppers\',\'offline\') THEN \'Offline to online shoppers\' WHEN token IN (\'recent inactive\',\'recent shoppers (less than 90 days)\', \'recent shoppers (30 - 90 days)\') THEN \'Recent shoppers (30 - 90 days)\' WHEN token IN (\'mid recent\', \'recent shoppers (90 - 180 days)\') THEN \'Recent shoppers (90 - 180 days)\' WHEN token IN (\'shoppers less than 360 days\', \'all shoppers\') THEN \'All shoppers\' WHEN token IN (\'lost customers\', \'dormant shoppers (over 180 days)\') THEN \'Dormant shoppers (over 180 days)\' WHEN token IN (\'birthday\',\'discount shoppers\') THEN \'Discount shoppers\' WHEN token IN (\'regional\',\'regional shoppers\') THEN \'Regional shoppers\' WHEN token IN (\'loyal customers\',\'snitch x\',\'x members\',\'x post enrollment\', \'X Perks\') THEN \'X members\' WHEN token IN (\'x eligible\',\'x activation\') THEN \'X eligible\' WHEN token IN (\'all\', \'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\',\'all users\') THEN \'All users\' WHEN token IN (\'snitch plus\', \'snitch plus shoppers\') THEN \'Snitch Plus shoppers\' WHEN token IN (\'best shoppers (high rfm)\',\'rfm\',\'high rfm\', \'best customers\') THEN \'Best shoppers (high rfm)\' WHEN token IN (\'occasion\',\'occasion shoppers\', \'occassion\', \'onam\') THEN \'Occasion shoppers\' WHEN token IN (\'time specific app users\',\'time specific\', \'behavior - time specific\') THEN \'Time specific app users\' WHEN token IN (\'streak\',\'streaks\',\'x perks\',\'bau perks\',\'benefits\',\'coins\',\'coins expiry\',\'x customers bau\',\'snitch x coins\', \'x streaks\') THEN \'X members\' ELSE NULL END AS l1, CASE WHEN token IN (\'category\', \'collecction\', \'collection\') THEN \'Category\' WHEN token IN (\'boxers\',\'blazers\',\'belts\',\'co-ords\',\'inner wear\',\'perfumes\',\'bags\',\'shirts\', \'sunglasses\',\'hoodies\',\'joggers & track\',\'joggers & trackpants\',\'joggers\',\'sweatshirts\', \'pyjamas\',\'cargo pants\',\'jackets\',\'shoes\',\'sneakers\',\'sweaters\',\'overshirt\', \'shorts\',\'t-shirts\',\'tshirt\',\'tshirts\',\'shirt\',\'cshirt\',\'jeans\',\'trousers\', \'core labs\',\'corelabs\',\'elevated essentials\',\'office ready\',\'snitch luxe\',\'streetwear\', \'cart\',\'cart category\',\'luxe wear\',\'luxewear\', \'new\',\'new arrivals\',\'wtw\',\'daily wtw\',\'x wtw\',\'bestsellers\', \'checks\') THEN \'Category\' WHEN token IN (\'capsule\',\'stars within\',\'utopia\') THEN \'Capsule\' WHEN token IN (\'fathers day\',\'ganesh chaturthi\',\'rakhi\',\'valentine sale\',\'diwali sale\', \'christmas sale\',\'holi sale\', \'occassion\', \'onam\') THEN \'Occasion\' WHEN token IN (\'sale\',\'mega sale\',\'minor sale\',\'featured sale\',\'black friday sale\',\'black friday\', \'deal of the day\',\'dod\',\'under 999\',\'independence day sale\',\'snitch birthday sale\', \'right to snitch\', \'shop your size store\',\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Sale\' WHEN token IN (\'x perks\',\'bau perks\',\'benefits\',\'coins\',\'coins expiry\',\'x customers bau\',\'streak\',\'streaks\') THEN \'BAU Perks\' WHEN token IN (\'offer\',\'offers\',\'15% off or lower\',\'20% off\',\'25% off\',\'15% off\',\'20% off\',\'25% off\') THEN \'Offers\' WHEN token IN (\'homepage\',\'home page\') THEN \'Home page\' WHEN token = \'nso\' THEN \'NSO\' ELSE NULL END AS l2, CASE WHEN token IN (\'shirts\',\'shirt\',\'cshirt\', \'checks\') THEN \'Shirts\' WHEN token IN (\'tshirt\',\'tshirts\') THEN \'T-Shirts\' WHEN token IN (\'jeans\',\'denim wear\', \'skinny jeans\') THEN \'Jeans\' WHEN token IN (\'shoes\',\'sneakers\',\'footwear\') THEN \'Shoes\' WHEN token IN (\'core labs\',\'corelabs\') THEN \'Core Labs\' WHEN token IN (\'elevated essentials\', \'elevated-essentials\') THEN \'Elevated Essentials\' WHEN token = \'office ready\' THEN \'Office ready\' WHEN token = \'streetwear\' THEN \'Streetwear\' WHEN token = \'essentials\' THEN \'Essentials\' WHEN token = \'snitch luxe\' THEN \'Luxewear\' WHEN token IN (\'cart\',\'cart category\') THEN \'Cart category\' WHEN token IN (\'new\',\'new arrivals\') THEN \'New\' WHEN token IN (\'wtw\',\'daily wtw\',\'x wtw\') THEN \'WTW\' WHEN token IN (\'bestsellers\',\'bestseller\') THEN \'Bestsellers\' WHEN token = \'stars within\' THEN \'Stars Within\' WHEN token = \'utopia\' THEN \'Utopia\' WHEN token = \'snitch birthday sale\' THEN \'Snitch Birthday sale\' WHEN token IN (\'black friday sale\',\'black friday\') THEN \'Black Friday sale\' WHEN token IN (\'independence day sale\', \'right to snitch\') THEN \'Independence Day sale\' WHEN token = \'christmas sale\' THEN \'Christmas sale\' WHEN token = \'holi sale\' THEN \'Holi sale\' WHEN token = \'onam\' THEN \'Onam Sale\' WHEN token = \'diwali sale\' THEN \'Diwali sale\' WHEN token = \'valentine sale\' THEN \'Valentine sale\' WHEN token IN (\'dod\',\'deal of the day\') THEN \'Deal of the day\' WHEN token = \'under 999\' THEN \'Under 999\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Shop your size store\' WHEN token IN (\'x perks\',\'bau perks\') THEN \'BAU perks\' WHEN token IN (\'coins\',\'coins expiry\',\'snitch x coins\') THEN \'Coins\' WHEN token IN (\'streak\',\'streaks\', \'x streaks\') THEN \'Streaks\' WHEN token IN (\'boxers\',\'blazers\',\'belts\',\'co-ords\',\'inner wear\',\'perfumes\',\'bags\', \'sunglasses\',\'hoodies\',\'joggers & track\',\'joggers & trackpants\',\'sweatshirts\', \'pyjamas\',\'cargo pants\',\'jackets\',\'sweaters\',\'overshirt\',\'shorts\') THEN INITCAP(token) ELSE NULL END AS l3_bucket, CASE WHEN token IN (\'linen\',\'linen shirts\',\'linen edit\') THEN \'Linen\' WHEN token = \'pshirts\' THEN \'Plain\' WHEN token IN (\'checks\', \'cshirt\') THEN \'Checks\' WHEN token IN (\'sjeans\', \'skinny jeans\') THEN \'Skinny\' WHEN token IN (\'stripes\') THEN \'Stripes\' WHEN token IN (\'bjeans\', \'baggy\') THEN \'Baggy\' WHEN token = \'graphics\' THEN \'Graphics\' WHEN token IN (\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN CASE token WHEN \'xs\' THEN \'XS\' WHEN \'s\' THEN \'S\' WHEN \'m\' THEN \'M\' WHEN \'l\' THEN \'L\' WHEN \'xl\' THEN \'XL\' WHEN \'xxl\' THEN \'XXL\' WHEN \'large\' THEN \'L\' END ELSE NULL END AS l4, CASE WHEN token=\'cross-sell\' THEN \'Cross sell\' WHEN token=\'upsell\' THEN \'Upsell\' WHEN token = \'msg91\' THEN \'msg91\' WHEN token = \'onextel\' THEN \'onextel\' ELSE NULL END AS l5, CASE WHEN token IN (\'pshirts\',\'sjeans\',\'bjeans\',\'linen\',\'linen shirts\',\'linen edit\',\'stripes\',\'revolution\') THEN \'Category\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\',\'dod\',\'deal of the day\') THEN \'Sale\' WHEN token IN (\'coins\',\'coins expiry\', \'snitch x coins\', \'x streaks\') THEN \'BAU Perks\' WHEN token IN (\'stars within\',\'utopia\') THEN \'Capsule\' ELSE NULL END AS l2_bfill, CASE WHEN token IN (\'pshirts\', \'graphics\') THEN \'T-Shirts\' WHEN token IN (\'sjeans\',\'bjeans\') THEN \'Jeans\' WHEN token IN (\'linen\',\'linen shirts\',\'linen edit\', \'stripes\') THEN \'Shirts\' WHEN token IN (\'behavior - size\',\'cutsize\',\'cutsize store\',\'xs\',\'s\',\'m\',\'l\',\'xl\',\'xxl\',\'large\') THEN \'Shop your size store\' WHEN token IN (\'dod\',\'deal of the day\') THEN \'Deal of the day\' WHEN token IN (\'coins\',\'coins expiry\') THEN \'Coins\' WHEN token=\'new arrivals\' THEN \'New\' WHEN token IN (\'wtw\',\'daily wtw\',\'x wtw\') THEN \'WTW\' WHEN token=\'bestsellers\' THEN \'Bestsellers\' WHEN token=\'stars within\' THEN \'Stars Within\' WHEN token=\'revolution\' THEN \'Revolution\' WHEN token=\'utopia\' THEN \'Utopia\' WHEN token IN (\'streak\',\'streaks\') THEN \'Streaks\' ELSE NULL END AS l3_bfill FROM tok ), rolled AS ( SELECT campaign_id, run_date, channel, MAX(l1) AS label_1, COALESCE(MAX(l2), MAX(l2_bfill)) AS label_2, COALESCE( MAX(CASE WHEN l2 IS NOT NULL THEN l3_bucket END), MAX(l3_bfill) ) AS label_3, MAX(l4) AS label_4, MAX(l5) AS label_5, LISTAGG(DISTINCT CASE WHEN COALESCE(l1,l2,l3_bucket,l4,l5,l2_bfill,l3_bfill) IS NULL THEN token ELSE NULL END, \', \' ) AS unmapped_labels FROM classified GROUP BY campaign_id, run_date, channel ) SELECT * FROM rolled ORDER BY campaign_id, run_date ); CREATE OR REPLACE TABLE campaign_reports_summary AS ( WITH CTE AS ( SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, a.OS as OS, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM snitch_db.maplemonk.CT_CLEVERTAP_DB a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\', \'Email\') AND a.Campaign_id NOT IN (\'1753099592\', \'1753100151\', \'1753100666\', \'1753175787\', \'1753101169\', \'1753101430\', \'1753253552\', \'1753254018\', \'1753254120\', \'1753339568\', \'1753339471\', \'1753264726\', \'1753957559\', \'1754053751\', \'1754053644\', \'1753350802\', \'1753351025\', \'1753356912\', \'1753356978\', \'1753256023\', \'1752834990\', \'1754053876\', \'1752136011\', \'1751022333\', \'1754054106\', \'1755008860\', \'1738771106\', \'1743780334\', \'1744023026\', \'1737203919\', \'1743826165\', \'1738829230\', \'1744024889\', \'1748166392\', \'1755065366\', \'1740978249\', \'1753166642\', \'1739856954\', \'1741259483\', \'1743825958\', \'1746798665\', \'1743780087\', \'1747825397\', \'1746790020\', \'1738909183\', \'1746788998\', \'1747824886\', \'1741166678\', \'1741168362\', \'1744025425\', \'1737004843\', \'1737005227\', \'1743779275\', \'1743779146\', \'1744023956\', \'1737203875\', \'1743779011\', \'1746007871\', \'1743825792\', \'1744024451\', \'1739795074\', \'1738829398\', \'1741163643\', \'1744023687\', \'1744022795\', \'1744025675\', \'1737204081\', \'1758539978\', \'1758534671\', \'1743690450\',\'1737005227\',\'1737004843\',\'1738771106\',\'1747733352\',\'1754054106\',\'1738909183\',\'1741163643\',\'1741169554\',\'1737203875\',\'1755065366\',\'1744025675\',\'1744023687\',\'1756881109\',\'1746007871\',\'1753256023\',\'1748335275\',\'1752136011\',\'1737203919\',\'1751022333\',\'1737451837\',\'1744022795\',\'1752834990\',\'1757497135\',\'1747991124\',\'1737455242\',\'1748314470\',\'1744023956\',\'1744023026\',\'1741259483\',\'1744025425\',\'1752566537\',\'1738829398\',\'1744024889\',\'1748314237\',\'1747991231\',\'1738829230\',\'1752566342\',\'1740978249\',\'1737204081\',\'1748166392\',\'1757494030\',\'1756881276\',\'1753100666\',\'1753101430\',\'1753100151\',\'1753099592\',\'1753175787\',\'1753101169\',\'1748335426\',\'1755854795\',\'1757316145\',\'1757335073\',\'1755864962\',\'1755866984\',\'1756204044\',\'1755867459\',\'1756206729\',\'1756712942\',\'1757334839\') AND labels not ilike \'%customer support%\' and labels not ilike \'%offline%\' AND a.created_by NOT IN (\'lohith.r@snitch.com\', \'ashwin.k@snitch.co.in\', \'nandini.t@snitch.com\', \'lohith.r@snitch.com\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL, a.OS UNION ALL SELECT COALESCE( TRY_TO_DATE(a.run_date, \'DD/MM/YY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, ROUND(a.CAMPAIGN_ID,0) AS campaign_id, a.CHANNEL AS channel, a.OS as OS, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(a.LABELS) AS labels, MAX(CONCAT_WS(CHAR(10)||CHAR(10), a.TITLE, a.MESSAGE)) AS details, MAX(a.who_query) AS segment, SUM(TRY_TO_NUMBER(a.total_sent_users)) AS total_sent_users, SUM(TRY_TO_NUMBER(a.total_clicked_users)) AS total_clicked_users, SUM(TRY_TO_NUMBER(a.total_viewed_users)) AS total_viewed_users, SUM(TRY_TO_NUMBER(a.total_delivered_users)) AS total_delivered_users, SUM(TRY_TO_NUMBER(a.total_sent_events)) AS total_sent_events, SUM(TRY_TO_NUMBER(a.total_viewed_events)) AS total_viewed_events, SUM(TRY_TO_NUMBER(a.total_clicked_events)) AS total_clicked_events, SUM(TRY_TO_NUMBER(a.total_delivered_events)) AS total_delivered_events FROM SNITCH_DB.MAPLEMONK.CT_CAMPAIGNS_JULY_AUG a WHERE a.channel IN (\'Sms\',\'Push Notification\',\'WhatsApp\', \'Email\') AND a.Campaign_id NOT IN (\'1753099592\', \'1753100151\', \'1753100666\', \'1753175787\', \'1753101169\', \'1753101430\', \'1753253552\', \'1753254018\', \'1753254120\', \'1753339568\', \'1753339471\', \'1753264726\', \'1753957559\', \'1754053751\', \'1754053644\', \'1753350802\', \'1753351025\', \'1753356912\', \'1753356978\', \'1753256023\', \'1752834990\', \'1754053876\', \'1752136011\', \'1751022333\', \'1754054106\', \'1755008860\', \'1738771106\', \'1743780334\', \'1744023026\', \'1737203919\', \'1743826165\', \'1738829230\', \'1744024889\', \'1748166392\', \'1755065366\', \'1740978249\', \'1753166642\', \'1739856954\', \'1741259483\', \'1743825958\', \'1746798665\', \'1743780087\', \'1747825397\', \'1746790020\', \'1738909183\', \'1746788998\', \'1747824886\', \'1741166678\', \'1741168362\', \'1744025425\', \'1737004843\', \'1737005227\', \'1743779275\', \'1743779146\', \'1744023956\', \'1737203875\', \'1743779011\', \'1746007871\', \'1743825792\', \'1744024451\', \'1739795074\', \'1738829398\', \'1741163643\', \'1744023687\', \'1744022795\', \'1744025675\', \'1737204081\', \'1758539978\', \'1758534671\', \'1743690450\',\'1737005227\',\'1737004843\',\'1738771106\',\'1747733352\',\'1754054106\',\'1738909183\',\'1741163643\',\'1741169554\',\'1737203875\',\'1755065366\',\'1744025675\',\'1744023687\',\'1756881109\',\'1746007871\',\'1753256023\',\'1748335275\',\'1752136011\',\'1737203919\',\'1751022333\',\'1737451837\',\'1744022795\',\'1752834990\',\'1757497135\',\'1747991124\',\'1737455242\',\'1748314470\',\'1744023956\',\'1744023026\',\'1741259483\',\'1744025425\',\'1752566537\',\'1738829398\',\'1744024889\',\'1748314237\',\'1747991231\',\'1738829230\',\'1752566342\',\'1740978249\',\'1737204081\',\'1748166392\',\'1757494030\',\'1756881276\',\'1753100666\',\'1753101430\',\'1753100151\',\'1753099592\',\'1753175787\',\'1753101169\',\'1748335426\',\'1755854795\',\'1757316145\',\'1757335073\',\'1755864962\',\'1755866984\',\'1756204044\',\'1755867459\',\'1756206729\',\'1756712942\',\'1757334839\') AND labels not ilike \'%customer support%\' and labels not ilike \'%offline%\' AND a.created_by NOT IN (\'lohith.r@snitch.com\', \'ashwin.k@snitch.co.in\', \'nandini.t@snitch.com\', \'lohith.r@snitch.com\') GROUP BY run_date, a.CAMPAIGN_ID, a.CHANNEL, a.OS ), marked AS ( SELECT campaign_id, channel, os, campaign_name, details, labels, run_date, DATE_TRUNC(\'week\', run_date) AS week_start, IFF(total_sent_events > 0, run_date, NULL) AS anchor_run_date, total_sent_users, total_clicked_users, total_viewed_users, total_delivered_users, total_sent_events, total_viewed_events, total_clicked_events, total_delivered_events FROM CTE ), anchor_days AS ( SELECT DISTINCT campaign_id, channel, os, week_start, anchor_run_date FROM marked WHERE anchor_run_date IS NOT NULL ), anchor_ranges AS ( SELECT campaign_id, channel, os, week_start, anchor_run_date AS range_start, COALESCE( LEAD(anchor_run_date) OVER ( PARTITION BY campaign_id, channel, week_start ORDER BY anchor_run_date ) - 1, anchor_run_date + 6 ) AS range_end FROM anchor_days ), coupon_codes AS ( SELECT campaign_id, details, run_date, channel, REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 ) AS coupon_code_raw, CASE WHEN REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 ) IS NOT NULL AND NOT REGEXP_LIKE(COALESCE(details,\'\'), \'\\$replacement\\$[[:space:]]*##w:\', \'i\') AND NOT ( COALESCE(details,\'\') ILIKE \'%unfinished%cart%\' OR COALESCE(details,\'\') ILIKE \'%abandon%\' OR COALESCE(details,\'\') ILIKE \'%abandoned%\' ) THEN UPPER(REGEXP_SUBSTR( details, \'(use[[:space:]]+code|coupon[[:space:]]*code|code)[[:space:]]*[-: ]?[[:space:]]*([A-Za-z0-9_-]{3,20})\', 1, 1, \'i\', 2 )) ELSE NULL END AS coupon_code FROM CTE ), codes_in_range AS ( SELECT ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start, MAX(c.coupon_code) AS coupon_code FROM anchor_ranges ar JOIN coupon_codes c ON c.campaign_id = ar.campaign_id AND c.channel = ar.channel AND c.run_date BETWEEN ar.range_start AND ar.range_end GROUP BY ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start ), coupon_codes_unique AS ( SELECT DISTINCT UPPER(coupon_code) AS coupon_code FROM coupon_codes WHERE coupon_code IS NOT NULL ), campaign_bucket_totals AS ( SELECT ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start AS correct_run_date, SUM(m.total_sent_events) AS total_sents, SUM(m.total_viewed_events) AS total_views, SUM(m.total_clicked_events) AS total_clicks, SUM(m.total_delivered_events) AS total_deliveries, SUM(m.total_sent_users) AS total_sent_users, SUM(m.total_viewed_users) AS total_viewed_users, SUM(m.total_clicked_users) AS total_clicked_users, SUM(m.total_delivered_users) AS total_delivered_users, MAX(m.campaign_name) AS campaign_name, MAX(m.details) AS details, MAX(m.labels) AS labels, MAX(cr.coupon_code) AS coupon_code FROM anchor_ranges ar JOIN marked m ON m.campaign_id = ar.campaign_id AND m.channel = ar.channel AND m.week_start = ar.week_start AND m.run_date BETWEEN ar.range_start AND ar.range_end LEFT JOIN codes_in_range cr ON cr.campaign_id = ar.campaign_id AND cr.channel = ar.channel AND cr.week_start = ar.week_start AND cr.range_start = ar.range_start GROUP BY ar.campaign_id, ar.channel, ar.os, ar.week_start, ar.range_start, cr.coupon_code ), coupon_charges AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, customer_id, order_name, order_timestamp::date AS charged_date, COUNT(line_item_id) AS quantity, SUM(gross_sales) AS total_sales, SUM(slashed_discount) AS total_sl_discount, SUM(discount) AS total_discount, MAX(discount_code) AS discount_code FROM SNITCH_DB.MAPLEMONK.FACT_ITEMS_SNITCH f JOIN coupon_codes_unique u ON UPPER(f.discount_code) = u.coupon_code GROUP BY 1,2,3,4 ), coupon_usage AS ( SELECT DISTINCT campaign_id, run_date, UPPER(coupon_code) AS coupon_code FROM coupon_codes WHERE coupon_code IS NOT NULL ), coupon_owner_per_order AS ( SELECT cc.order_name, cc.charged_date, cc.total_sales, cc.discount_code, cu.campaign_id, cu.run_date, ROW_NUMBER() OVER ( PARTITION BY cc.order_name ORDER BY cu.run_date DESC, cu.campaign_id ) AS rn FROM coupon_charges cc JOIN coupon_usage cu ON UPPER(cc.discount_code) = cu.coupon_code AND cu.run_date <= cc.charged_date ), coupon_attributed_orders AS ( SELECT order_name, charged_date, total_sales, discount_code, campaign_id FROM coupon_owner_per_order WHERE UPPER(discount_code) NOT IN (\'APP10\', \'XDAY\') and rn = 1 ), coupon_by_bucket AS ( SELECT ar.campaign_id, ar.channel, ar.range_start AS correct_run_date, COUNT(DISTINCT cao.order_name) AS coupon_orders, SUM(cao.total_sales) AS coupon_revenue FROM coupon_attributed_orders cao JOIN anchor_ranges ar ON ar.campaign_id = cao.campaign_id GROUP BY 1,2,3 ), clicks_charges AS ( SELECT TRY_TO_NUMBER(c_id) AS campaign_id, CASE WHEN LOWER(campaign_channel)=\'push\' THEN \'Push Notification\' ELSE campaign_channel END AS channel, click_date, order_name, total_sales FROM ct_click_charge ), clicks_charges_dedup AS ( SELECT * FROM ( SELECT campaign_id, channel, click_date, order_name, total_sales, ROW_NUMBER() OVER (PARTITION BY campaign_id, channel, order_name ORDER BY click_date DESC) AS rn FROM clicks_charges ) WHERE rn = 1 ), clicks_charges_dedup_no_coupon AS ( SELECT ccd.* FROM clicks_charges_dedup ccd LEFT JOIN coupon_attributed_orders cao ON cao.order_name = ccd.order_name WHERE cao.order_name IS NULL ), charges_attributed AS ( SELECT ar.campaign_id, ar.channel, ar.range_start AS correct_run_date, ccd.order_name, ccd.total_sales FROM anchor_ranges ar JOIN clicks_charges_dedup_no_coupon ccd ON ccd.campaign_id = ar.campaign_id AND ccd.channel = ar.channel AND ccd.click_date BETWEEN ar.range_start AND ar.range_end ) SELECT cbt.campaign_id, cbt.channel, cbt.os, cbt.campaign_name, cbt.details, cbt.correct_run_date AS run_date, cbt.labels, clc.label_1, clc.label_2, clc.label_3, clc.label_4, clc.label_5, cbt.total_sents, cbt.total_deliveries, cbt.total_views, cbt.total_clicks, cbt.coupon_code, CASE WHEN cbt.channel = \'Push Notification\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_sents,0),2) WHEN cbt.channel = \'Sms\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_deliveries,0),2) WHEN cbt.channel = \'WhatsApp\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_views,0),2) WHEN cbt.channel = \'Email\' THEN ROUND(cbt.total_clicks/NULLIF(cbt.total_sents,0),2) ELSE 0 END AS ctr, COALESCE(MAX(cbb.coupon_orders), 0) AS coupon_orders, COALESCE(MAX(cbb.coupon_revenue), 0) AS coupon_revenue, COALESCE(COUNT(DISTINCT ca.order_name), 0) + COALESCE(MAX(cbb.coupon_orders), 0) AS total_orders, CASE WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date BETWEEN \'2025-09-13\' AND \'2025-09-30\' THEN COALESCE(MAX(cbb.coupon_revenue), 0) ELSE COALESCE(SUM(ca.total_sales), 0) + COALESCE(MAX(cbb.coupon_revenue), 0) END AS attributed_revenue, CASE WHEN cbt.channel = \'Push Notification\' THEN 0 WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date < \'2025-09-01\' THEN cbt.total_deliveries * 0.10 WHEN cbt.channel = \'Sms\' THEN cbt.total_deliveries * 0.095 WHEN cbt.channel = \'WhatsApp\' AND cbt.correct_run_date < \'2025-09-01\' THEN cbt.total_deliveries * 0.71 WHEN cbt.channel = \'WhatsApp\' THEN cbt.total_deliveries * 0.69 ELSE 0 END AS spends, ROUND( ( CASE WHEN cbt.channel = \'Sms\' AND cbt.correct_run_date BETWEEN \'2025-09-13\' AND \'2025-09-30\' THEN COALESCE(MAX(cbb.coupon_revenue), 0) ELSE COALESCE(SUM(ca.total_sales), 0) + COALESCE(MAX(cbb.coupon_revenue), 0) END ) / NULLIF( CASE WHEN cbt.channel = \'Push Notification\' THEN 0 WHEN cbt.channel = \'Sms\' THEN cbt.total_deliveries * 0.10 WHEN cbt.channel = \'WhatsApp\' THEN cbt.total_deliveries * 0.71 ELSE 0 END, 0 ), 2 ) AS roas FROM campaign_bucket_totals cbt LEFT JOIN charges_attributed ca ON ca.campaign_id = cbt.campaign_id AND ca.channel = cbt.channel AND ca.correct_run_date = cbt.correct_run_date LEFT JOIN coupon_by_bucket cbb ON cbb.campaign_id = cbt.campaign_id AND cbb.channel = cbt.channel AND cbb.correct_run_date = cbt.correct_run_date LEFT JOIN campaign_labels_cleaned clc ON clc.campaign_id = cbt.campaign_id AND clc.run_date = cbt.correct_run_date WHERE labels NOT ILIKE \'%offline%\' GROUP BY cbt.campaign_id, cbt.channel, cbt.os, cbt.campaign_name, cbt.details, clc.label_1, clc.label_2, clc.label_3, clc.label_4, clc.label_5, cbt.correct_run_date, cbt.total_sents, cbt.total_views, cbt.total_clicks, cbt.total_deliveries, cbt.labels, cbt.coupon_code ORDER BY cbt.correct_run_date DESC, cbt.campaign_id, cbt.channel ); CREATE OR REPLACE TABLE journey_reports_summary AS ( WITH journey_base AS ( SELECT TRY_TO_NUMBER(j.journey_id) AS journey_id, j.journey_name, TRY_TO_NUMBER(j.node_id) AS node_id, j.node_type, CASE WHEN LOWER(j.channel_segment_controller_type) IN (\'push\',\'push notification\') THEN \'Push Notification\' WHEN LOWER(j.channel_segment_controller_type) = \'sms\' THEN \'Sms\' WHEN LOWER(j.channel_segment_controller_type) = \'whatsapp\' THEN \'WhatsApp\' WHEN LOWER(j.channel_segment_controller_type) = \'email\' THEN \'Email\' END AS channel, TRY_TO_NUMBER(TRIM(tok.value)) AS campaign_id, COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE AS start_date, CASE WHEN j.journey_end_time ILIKE \'%never%\' OR j.journey_end_time IS NULL OR TRIM(j.journey_end_time) = \'\' THEN NULL ELSE COALESCE( TRY_TO_TIMESTAMP_NTZ(j.journey_start_time || \', 2025\', \'MON DD, HH24:MI, YYYY\'), TRY_TO_TIMESTAMP_NTZ(j.journey_start_time, \'MON DD, HH24:MI\') )::DATE END AS end_date, COALESCE(SUM(TRY_TO_NUMBER(j.total_sent)) , 0) AS total_sents, COALESCE(SUM(TRY_TO_NUMBER(j.total_delivered)) , 0) AS total_delivered, COALESCE(SUM(TRY_TO_NUMBER(j.total_viewed)) , 0) AS total_views, COALESCE(SUM(TRY_TO_NUMBER(j.total_clicked)), 0) AS total_clicks, j.journey_status, COALESCE(TRY_TO_DATE(j.upload_date,\'DD/MM/YY\'), TRY_TO_DATE(j.upload_date,\'DD-MM-YYYY\')) as run_date FROM ct_journey_reports j, TABLE( SPLIT_TO_TABLE( REGEXP_REPLACE(j.campaign_segment_controller_id, \'\\s*\\|\\s*\', \',\'), \',\' ) ) tok WHERE TRY_TO_NUMBER(TRIM(tok.value)) IS NOT NULL AND JOURNEY_ID IN (\'12\', \'15\', \'16\', \'20\', \'17\', \'85\', \'122\', \'127\', \'118\', \'114\', \'115\', \'119\', \'120\', \'112\', \'117\', \'131\', \'132\' , \'133\') AND campaign_id NOT IN (\'5150\', \'5142\', \'5149\', \'5143\', \'5148\', \'5147\', \'5144\', \'5145\', \'5146\', \'5122\', \'5132\', \'5133\', \'5123\', \'5130\', \'5131\', \'5124\', \'5128\', \'5129\', \'5127\', \'5126\', \'5125\', \'5104\', \'5113\', \'5112\', \'5105\', \'5111\', \'5110\', \'5106\', \'5109\', \'5108\', \'5094\', \'5077\', \'5093\', \'5078\', \'5092\', \'5091\', \'5079\', \'5090\', \'5089\', \'5080\', \'5087\', \'5088\', \'5081\', \'5086\', \'5085\', \'5082\', \'5083\', \'5084\', \'5137\', \'5121\', \'5134\', \'5135\', \'5136\', \'5075\', \'5076\', \'5102\', \'5103\', \'5107\', \'5140\', \'5141\', \'5117\', \'5118\', \'5120\') GROUP BY 1,2,3,4,5,6,7,8,13,14 ), clicks_charges AS ( SELECT TRY_TO_NUMBER(C_ID) AS campaign_id, CASE WHEN LOWER(CAMPAIGN_CHANNEL) = \'push\' THEN \'Push Notification\' ELSE CAMPAIGN_CHANNEL END AS channel, CLICK_DATE AS click_date, ORDER_NAME AS order_name, TOTAL_SALES AS total_sales FROM ct_click_charge WHERE LENGTH(C_ID) IN (4,5) ), charges_attributed AS ( SELECT j.journey_id, j.journey_name, j.campaign_id, j.channel, j.start_date, j.run_date, cc.order_name, cc.total_sales FROM journey_base j JOIN clicks_charges cc ON cc.campaign_id = j.campaign_id AND (cc.channel = j.channel OR j.channel IS NULL) AND cc.click_date = j.run_date ) SELECT j.journey_id, j.journey_name, j.campaign_id, j.channel, j.start_date, j.run_date, j.total_sents, j.total_delivered, j.total_views, j.total_clicks, j.journey_status, CASE WHEN j.channel = \'Push Notification\' THEN ROUND(j.total_clicks/NULLIF(j.total_sents,0),2) WHEN j.channel = \'Sms\' THEN ROUND(j.total_clicks/NULLIF(j.total_sents,0),2) WHEN j.channel = \'WhatsApp\' THEN ROUND(j.total_clicks/NULLIF(j.total_views,0),2) WHEN j.channel = \'Email\' THEN ROUND(j.total_clicks/NULLIF(j.total_sents,0),2) ELSE 0 END AS CTR, COALESCE(COUNT(DISTINCT ca.order_name), 0) AS total_orders, COALESCE(SUM(ca.total_sales), 0) AS attributed_revenue, CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.1 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 ELSE 0 END AS spends, ROUND(COALESCE(SUM(ca.total_sales), 0)/ NULLIF((CASE WHEN j.channel = \'Push Notification\' THEN 0 WHEN j.channel = \'Sms\' THEN j.total_delivered * 0.1 WHEN j.channel = \'WhatsApp\' THEN j.total_delivered * 0.71 ELSE 0 END),0),2) AS ROAS FROM journey_base j LEFT JOIN charges_attributed ca ON ca.campaign_id = j.campaign_id AND ca.channel = j.channel AND ca.run_date = j.run_date GROUP BY j.journey_id, j.journey_name, j.campaign_id, j.channel, j.journey_status, j.start_date, j.run_date, j.total_sents, j.total_delivered, j.total_views, j.total_clicks ORDER BY j.campaign_id, j.channel, j.start_date ); CREATE OR REPLACE TABLE daily_retention_revenue AS ( WITH CTE AS ( SELECT order_timestamp::date AS run_date, SUM(gross_sales) as revenue FROM fact_items_snitch WHERE order_timestamp::date >= \'2025-03-01\' GROUP BY 1 ), push_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As Push_camp_rev, SUM(Spends) AS Push_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Push Notification\' GROUP BY 1 ), push_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS push_jour_rev, SUM(Spends) AS push_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'Push Notification\' GROUP BY 1 ), SMS_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As sms_camp_rev, SUM(Spends) AS sms_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Sms\' GROUP BY 1 ), SMS_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS sms_jour_rev, SUM(Spends) AS sms_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'Sms\' GROUP BY 1 ), WA_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As wa_camp_rev, SUM(Spends) AS wa_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'WhatsApp\' GROUP BY 1 ), WA_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS wa_jour_rev, SUM(Spends) AS wa_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'WhatsApp\' GROUP BY 1 ), email_camp_data AS ( SELECT run_date, SUM(ATTRIBUTED_REVENUE) As email_camp_rev, SUM(Spends) AS email_camp_spends FROM CAMPAIGN_REPORTS_SUMMARY WHERE CHANNEL = \'Email\' GROUP BY 1 ), email_jour_data AS ( SELECT run_date, SUM(attributed_revenue) AS email_jour_rev, SUM(Spends) AS email_jour_spends FROM JOURNEY_REPORTS_SUMMARY WHERE channel = \'email\' GROUP BY 1 ) SELECT a.*, Coalesce(b.push_camp_rev,0) as push_camp_rev, coalesce(x.push_jour_rev,0) as push_jour_rev, coalesce(c.sms_camp_rev,0) as sms_camp_rev, coalesce(c.sms_camp_spends,0) as sms_camp_spends, coalesce(y.sms_jour_rev,0) as sms_jour_rev, coalesce(y.sms_jour_spends,0) as sms_jour_spends, coalesce(d.wa_camp_rev,0) as wa_camp_rev, coalesce(d.wa_camp_spends,0) as wa_camp_spends, coalesce(z.wa_jour_rev,0) as wa_jour_rev, coalesce(z.wa_jour_spends,0) as wa_jour_spends, coalesce(e.email_camp_rev,0) as email_camp_rev, coalesce(w.email_jour_rev,0) as email_jour_rev FROM CTE a LEFT JOIN push_camp_data b on a.run_date = b.run_date LEFT JOIN push_jour_data x on a.run_date = x.run_date LEFT JOIN sms_camp_data c on a.run_date = c.run_date LEFT JOIN sms_jour_data y on a.run_date = y.run_date LEFT JOIN wa_camp_data d on a.run_date = d.run_date LEFT JOIN wa_jour_data z on a.run_date = z.run_date LEFT JOIN email_camp_data e on a.run_date = e.run_date LEFT JOIN email_jour_data w on a.run_date = w.run_date );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            